<?php
declare(strict_types=1);namespace App\Application\Underwriting;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter,Shared\CanonicalJson};use App\Models\{DisclosureSchemaVersion,InsuranceLine,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class DisclosureGovernanceService{public function __construct(private CanonicalJson$json,private AuditWriter$audit,private OutboxWriter$outbox){}public function create(InsuranceLine$line,array$d,User$actor):DisclosureSchemaVersion{return DB::transaction(function()use($line,$d,$actor){$v=(DisclosureSchemaVersion::where('insurance_line_id',$line->id)->lockForUpdate()->pluck('version')->max()??0)+1;$s=DisclosureSchemaVersion::create([...$d,'insurance_line_id'=>$line->id,'version'=>$v,'status'=>'DRAFT','schema_hash'=>$this->json->hash($d['questions']),'created_by'=>$actor->id]);$this->audit->record('disclosure.schema.created','disclosure_schema',$s->id,['version'=>$v]);return$s;});}public function approve(DisclosureSchemaVersion$s,User$actor):DisclosureSchemaVersion{if($s->status!=='DRAFT')throw ValidationException::withMessages(['status'=>__('wave3.schema_not_draft')]);if($s->created_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave3.maker_checker')]);if($this->json->hash($s->questions)!==$s->schema_hash)throw ValidationException::withMessages(['questions'=>__('wave3.schema_hash_mismatch')]);return DB::transaction(function()use($s,$actor){DisclosureSchemaVersion::where('insurance_line_id',$s->insurance_line_id)->where('status','APPROVED')->update(['status'=>'RETIRED']);$s->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$this->audit->record('disclosure.schema.approved','disclosure_schema',$s->id,['version'=>$s->version]);$this->outbox->record('disclosure.schema.approved','disclosure_schema',$s->id,['schema_id'=>$s->id]);return$s->refresh();});}}
